// Inspector for the layout slot being edited on the canvas (multicam mode).

import { useEditor, useProject } from "@mcut/react";
import {
  createLayoutId,
  type Layout,
  type LayoutSlot,
} from "@mcut/timeline";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { useEditorUI } from "./editor-ui";
import { roundRect, safeAreaRect, saveLayoutSlot } from "./layout-slot-editor";
import { ChoiceRow, FieldRow, NumberField, Section } from "./inspector-fields";
import { FrameFields, type FrameTarget } from "./frame-section";
import { PresetMenu } from "./preset-menu";
import { RadiusRow, readStylePreset, StrokeFields } from "./style-fields";

/** Aspect chips for quick crops: keep the slot's center and pixel width. */
export const SLOT_ASPECTS: ReadonlyArray<readonly [label: string, ratio: number]> = [
  ["1:1", 1],
  ["3:4", 3 / 4],
  ["4:3", 4 / 3],
  ["16:9", 16 / 9],
  ["9:16", 9 / 16],
];

/**
 * Inspector for the layout slot being edited on the canvas (multicam mode).
 * The canvas does direct manipulation (move / resize / crop-pan); everything
 * with a value lives here, in the same controls as element properties.
 */
export function LayoutSlotInspector({ layout, className }: { layout: Layout; className?: string }) {
  const engine = useEditor();
  const project = useProject();
  const { editingSlotIndex, setEditingSlotIndex } = useEditorUI();
  const W = project.width;
  const H = project.height;
  const index =
    editingSlotIndex !== null && layout.slots[editingSlotIndex] !== undefined
      ? editingSlotIndex
      : null;
  const slot = index !== null ? layout.slots[index]! : null;
  const safe = safeAreaRect(W, H);

  const save = (patch: Partial<LayoutSlot>, options?: { history?: boolean }) => {
    if (index !== null) saveLayoutSlot(engine, layout, index, patch, options);
  };
  const saveRect = (rect: LayoutSlot["rect"], options?: { history?: boolean }) =>
    save({ rect: roundRect(rect) }, options);

  const applyAspect = (ratio: number) => {
    if (!slot) return;
    // Hold the center and the pixel width; derive the height (shrink to fit).
    let w = slot.rect.w;
    let h = (slot.rect.w * W) / ratio / H;
    if (h > 1) {
      w /= h;
      h = 1;
    }
    const cx = slot.rect.x + slot.rect.w / 2;
    const cy = slot.rect.y + slot.rect.h / 2;
    saveRect({ x: cx - w / 2, y: cy - h / 2, w, h });
  };

  // The shared frame editor drives the slot through px-rect reads/writes;
  // normalized storage stays an adapter detail.
  const slotFrame: FrameTarget | null =
    slot === null
      ? null
      : {
          canvas: { width: W, height: H },
          safe: { x: safe.x * W, y: safe.y * H, width: safe.w * W, height: safe.h * H },
          rect: {
            x: slot.rect.x * W,
            y: slot.rect.y * H,
            width: slot.rect.w * W,
            height: slot.rect.h * H,
          },
          minSize: 16,
          setRect: (patch) => {
            const next = { ...slot.rect };
            if (patch.x !== undefined) next.x = patch.x / W;
            if (patch.y !== undefined) next.y = patch.y / H;
            if (patch.width !== undefined) next.w = patch.width / W;
            if (patch.height !== undefined) next.h = patch.height / H;
            saveRect(next);
          },
        };

  const saveAsPreset = () => {
    const name = window.prompt("Save this layout as a new preset:", `${layout.name} copy`);
    if (!name?.trim()) return;
    try {
      engine.dispatch({
        type: "saveLayout",
        layout: { ...layout, id: createLayoutId(), name: name.trim() },
      });
      toast.success(`"${name.trim()}" added to the layout bank`);
    } catch {
      toast.error("Could not save the preset");
    }
  };

  return (
    <div className={cn("flex flex-col gap-1 p-3", className)}>
      <div className="flex items-center gap-2 pb-1">
        <span className="flex-1 truncate text-xs font-semibold" title={layout.name}>
          Layout · {layout.name}
        </span>
        <Button variant="secondary" size="xs" onClick={saveAsPreset}>
          Save as preset
        </Button>
      </div>

      <Section title="Slots">
        {layout.slots.map((s, i) => (
          <button
            key={`${s.source}-${i}`}
            type="button"
            className={cn(
              "flex items-center justify-between rounded-md border px-2 py-1 text-xs capitalize",
              i === index
                ? "border-primary bg-primary/10 text-foreground"
                : "border-transparent text-muted-foreground hover:bg-foreground/5 hover:text-foreground",
            )}
            onClick={() => setEditingSlotIndex(i)}
          >
            {s.source}
            <span className="text-2xs text-muted-foreground normal-case">
              {layout.slots.length > 1 && i === layout.slots.length - 1
                ? "top"
                : layout.slots.length > 1 && i === 0
                  ? "bottom"
                  : ""}
            </span>
          </button>
        ))}
        {slot === null && (
          <p className="text-2xs text-muted-foreground">
            Click a slot above or on the canvas to style it.
          </p>
        )}
      </Section>

      {slot && index !== null && slotFrame && (
        <>
          <Section title="Frame">
            <FrameFields target={slotFrame} />
            <FieldRow
              label="Aspect"
              title="Crop the slot to an aspect (keeps its center and width)"
            >
              <div className="grid min-w-0 flex-1 grid-cols-3 gap-1">
                {SLOT_ASPECTS.map(([label, ratio]) => (
                  <Button
                    key={label}
                    size="xs"
                    variant="outline"
                    className="min-w-0 px-1"
                    onClick={() => applyAspect(ratio)}
                  >
                    {label}
                  </Button>
                ))}
              </div>
            </FieldRow>
            <FieldRow label="Fill">
              <Button
                size="xs"
                variant="outline"
                className="flex-1"
                title="Fit the slot to the safe area"
                onClick={() => saveRect(safe)}
              >
                Safe area
              </Button>
              <Button
                size="xs"
                variant="outline"
                className="flex-1"
                title="Fill the whole canvas"
                onClick={() => saveRect({ x: 0, y: 0, w: 1, h: 1 })}
              >
                Screen
              </Button>
            </FieldRow>
          </Section>

          <Section
            title="Style"
            actions={
              <PresetMenu
                kind="style"
                getValues={() => ({
                  fit: slot.fit,
                  cornerRadius: slot.cornerRadius,
                  shadow: slot.shadow,
                  stroke: slot.stroke ?? null,
                })}
                onApply={(values) => {
                  // Tolerant apply: slots keep the keys they understand; a
                  // full element shadow lands as the slot's boolean look.
                  const preset = readStylePreset(values);
                  const patch: Partial<LayoutSlot> = {};
                  if (preset.fit) patch.fit = preset.fit;
                  if (preset.cornerRadius !== undefined) patch.cornerRadius = preset.cornerRadius;
                  if (preset.stroke !== undefined) patch.stroke = preset.stroke ?? undefined;
                  if (preset.shadow !== undefined) {
                    patch.shadow =
                      typeof preset.shadow === "boolean" ? preset.shadow : preset.shadow !== null;
                  }
                  save(patch);
                }}
              />
            }
          >
            <ChoiceRow
              label="Fit"
              value={slot.fit}
              options={["cover", "contain"] as const}
              onCommit={(fit) => save({ fit })}
            />
            <RadiusRow
              value={slot.cornerRadius}
              onCommit={(cornerRadius) => save({ cornerRadius })}
            />
            <StrokeFields
              value={slot.stroke}
              onCommit={(stroke) => save({ stroke })}
            />
            <FieldRow label="Shadow">
              <Switch
                aria-label="Shadow"
                checked={slot.shadow}
                onCheckedChange={(shadow) => save({ shadow })}
              />
            </FieldRow>
          </Section>

          {slot.fit === "cover" && (
            <Section title="Crop" onReset={() => save({ focus: { x: 0.5, y: 0.5 } })}>
              <NumberField
                label="Focus X"
                value={Math.round((slot.focus?.x ?? 0.5) * 100)}
                min={0}
                max={100}
                unit="%"
                scrubPerPx={0.5}
                onCommit={(pct) => save({ focus: { y: slot.focus?.y ?? 0.5, x: pct / 100 } })}
              />
              <NumberField
                label="Focus Y"
                value={Math.round((slot.focus?.y ?? 0.5) * 100)}
                min={0}
                max={100}
                unit="%"
                scrubPerPx={0.5}
                onCommit={(pct) => save({ focus: { x: slot.focus?.x ?? 0.5, y: pct / 100 } })}
              />
              <p className="text-2xs text-muted-foreground">
                Or double-click the slot on the canvas and drag to pan the source inside the
                frame.
              </p>
            </Section>
          )}

          <p className="text-2xs text-muted-foreground">
            On the canvas: drag to move (snaps to the safe area, center, and other slots — hold ⌘
            to disable), corners resize with the aspect locked (Shift frees it), arrows nudge by
            1px.
          </p>
        </>
      )}
    </div>
  );
}

/**
 * Canvas aspect-ratio presets (platform delivery formats). Applying one sets
 * the project's width/height via `updateProject`; fps is untouched. Elements
 * keep their transforms — center-origin coordinates make a canvas resize a
 * reframe, not a layout break.
 */
export const ASPECT_PRESETS = [
  { id: "16-9", label: "16:9", hint: "YouTube / landscape", width: 1920, height: 1080 },
  { id: "9-16", label: "9:16", hint: "Shorts / Reels / TikTok", width: 1080, height: 1920 },
  { id: "1-1", label: "1:1", hint: "Square", width: 1080, height: 1080 },
  { id: "4-5", label: "4:5", hint: "Portrait feed", width: 1080, height: 1350 },
] as const;

export type AspectPreset = (typeof ASPECT_PRESETS)[number];

export function matchesAspect(project: { width: number; height: number }, preset: AspectPreset): boolean {
  return project.width * preset.height === project.height * preset.width;
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";
import type { PreviewQuality } from "@mcut/react";
import { clamp } from "./math";

/** A live drop ghost while dragging media over the timeline. */
export interface DropPreview {
  /** Target track id, or "new-track" for the phantom top lane. */
  trackId: string;
  startMs: number;
  durationMs: number;
  label: string;
}

// ---------------------------------------------------------------------------
// Drag overlay stores
// ---------------------------------------------------------------------------
// Drop ghost and snap guide update on every pointermove during a drag. They
// live in tiny external stores (not React context state) so a drag move
// re-renders only the overlay components that subscribe via useDropPreview/
// useSnapGuideMs — never the whole editor tree.

interface OverlayStore<T> {
  get: () => T;
  set: (value: T) => void;
  subscribe: (listener: () => void) => () => void;
}

function createOverlayStore<T>(initial: T, equals: (a: T, b: T) => boolean): OverlayStore<T> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next: T) => {
      if (equals(value, next)) return;
      value = next;
      for (const listener of listeners) listener();
    },
    subscribe: (listener: () => void) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

function dropPreviewEquals(a: DropPreview | null, b: DropPreview | null): boolean {
  if (a === b) return true;
  if (!a || !b) return false;
  return (
    a.trackId === b.trackId &&
    a.startMs === b.startMs &&
    a.durationMs === b.durationMs &&
    a.label === b.label
  );
}

interface DragOverlayStores {
  dropPreview: OverlayStore<DropPreview | null>;
  snapGuide: OverlayStore<number | null>;
}

const DragOverlayContext = createContext<DragOverlayStores | null>(null);

function useDragOverlayStores(): DragOverlayStores {
  const stores = useContext(DragOverlayContext);
  if (!stores) throw new Error("drag overlay hooks must be used inside <EditorUIProvider>");
  return stores;
}

/** The live drop ghost, or null when no media drag is over the timeline. */
export function useDropPreview(): DropPreview | null {
  const { dropPreview } = useDragOverlayStores();
  return useSyncExternalStore(dropPreview.subscribe, dropPreview.get, () => null);
}

/** The snap guide line (timeline ms), or null when nothing is snapping. */
export function useSnapGuideMs(): number | null {
  const { snapGuide } = useDragOverlayStores();
  return useSyncExternalStore(snapGuide.subscribe, snapGuide.get, () => null);
}

export type EditorTheme = "dark" | "light";

/**
 * Editing modes are VIEWS, not document state: they re-emphasize affordances
 * (multicam = layout bank + 1–9 switching) over the same project.
 */
export type EditorMode = "edit" | "multicam" | "collage";

/**
 * Timeline pointer tools (Premiere's tool palette): select is the default
 * move/trim tool; ripple/roll change what the trim handles do; slip/slide
 * change what dragging the clip body does.
 */
export type TimelineTool = "select" | "ripple" | "roll" | "slip" | "slide";

/**
 * Placement mode for inserts and drops (Kdenlive's taxonomy): normal rejects
 * collisions, overwrite clears the landing range, insert ripples everything
 * after the point to the right.
 */
export type TimelineEditMode = "normal" | "overwrite" | "insert";

export interface EditorUIValue {
  /** Editor color theme (warm grey light/dark; tokens in globals.css). */
  theme: EditorTheme;
  setTheme: (value: EditorTheme) => void;
  /** Current editing mode (session-scoped; not persisted). */
  mode: EditorMode;
  setMode: (value: EditorMode) => void;
  /** Layout whose slots are being edited on the canvas (multicam mode). */
  editingLayoutId: string | null;
  setEditingLayoutId: (value: string | null) => void;
  /**
   * Slot edit state: index of the slot (within the editing layout) whose
   * properties the inspector shows. Shared so the canvas overlay and the
   * properties panel select and style the same slot.
   */
  editingSlotIndex: number | null;
  setEditingSlotIndex: (value: number | null) => void;
  /** Text element being edited INLINE on the canvas (double-click to enter). */
  editingTextId: string | null;
  setEditingTextId: (value: string | null) => void;
  /** Timeline zoom. */
  pxPerMs: number;
  setPxPerMs: (value: number) => void;
  /** Zoom keeping `anchorMs` under the same screen x (used by ⌘+wheel). */
  zoomBy: (factor: number, anchorMs?: number) => void;
  snapEnabled: boolean;
  setSnapEnabled: (value: boolean) => void;
  /** Active timeline pointer tool (session-scoped). */
  timelineTool: TimelineTool;
  setTimelineTool: (value: TimelineTool) => void;
  /** Placement mode for inserts/drops (session-scoped). */
  editMode: TimelineEditMode;
  setEditMode: (value: TimelineEditMode) => void;
  /** Drop a dissolve when a dragged clip is pushed flush against a neighbor. */
  autoCrossfade: boolean;
  setAutoCrossfade: (value: boolean) => void;
  /** Preview raster resolution ('auto' fits the pane; numbers cap the short side). */
  previewQuality: PreviewQuality;
  setPreviewQuality: (value: PreviewQuality) => void;
  /** Publish the drop ghost (read it via useDropPreview — it's not in this context). */
  setDropPreview: (value: DropPreview | null) => void;
  /** The timeline's horizontal scroll container (for zoom anchoring/auto-scroll). */
  timelineScrollRef: React.RefObject<HTMLDivElement | null>;
  /** Publish the snap guide line (read it via useSnapGuideMs). */
  setSnapGuideMs: (value: number | null) => void;
}

export const MIN_PX_PER_MS = 0.004;
export const MAX_PX_PER_MS = 0.6;
/** Left header gutter width inside the timeline, px. */
export const TIMELINE_HEADER_WIDTH = 288;

const EditorUIContext = createContext<EditorUIValue | null>(null);

const PREFS_KEY = "mcut:ui";

function loadPrefs(): {
  pxPerMs?: number;
  snapEnabled?: boolean;
  autoCrossfade?: boolean;
  theme?: EditorTheme;
  previewQuality?: PreviewQuality;
} {
  if (typeof window === "undefined") return {};
  try {
    return JSON.parse(window.localStorage.getItem(PREFS_KEY) ?? "{}");
  } catch {
    return {};
  }
}

function isPreviewQuality(value: unknown): value is PreviewQuality {
  return value === "auto" || value === "full" || (typeof value === "number" && value > 0);
}

export function EditorUIProvider({ children }: { children: ReactNode }) {
  const [pxPerMs, setPxPerMsState] = useState(0.05);
  const [snapEnabled, setSnapEnabledState] = useState(true);
  const [timelineTool, setTimelineTool] = useState<TimelineTool>("select");
  const [editMode, setEditMode] = useState<TimelineEditMode>("normal");
  const [autoCrossfade, setAutoCrossfadeState] = useState(false);
  const [previewQuality, setPreviewQualityState] = useState<PreviewQuality>("auto");
  const [theme, setThemeState] = useState<EditorTheme>("dark");
  const [mode, setModeState] = useState<EditorMode>("edit");
  const [editingLayoutId, setEditingLayoutIdState] = useState<string | null>(null);
  const [editingSlotIndex, setEditingSlotIndex] = useState<number | null>(null);
  const [editingTextId, setEditingTextId] = useState<string | null>(null);
  const setEditingLayoutId = useCallback((value: string | null) => {
    setEditingLayoutIdState(value);
    setEditingSlotIndex(null); // slot selection is scoped to one layout
  }, []);
  const setMode = useCallback((value: EditorMode) => {
    setModeState(value);
    // Leaving a mode always exits slot editing.
    setEditingLayoutIdState(null);
    setEditingSlotIndex(null);
    setEditingTextId(null);
  }, []);
  const [overlayStores] = useState<DragOverlayStores>(() => ({
    dropPreview: createOverlayStore<DropPreview | null>(null, dropPreviewEquals),
    snapGuide: createOverlayStore<number | null>(null, Object.is),
  }));
  const setDropPreview = useCallback(
    (value: DropPreview | null) => overlayStores.dropPreview.set(value),
    [overlayStores],
  );
  const setSnapGuideMs = useCallback(
    (value: number | null) => overlayStores.snapGuide.set(value),
    [overlayStores],
  );
  const timelineScrollRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    // Apply persisted prefs after hydration (a lazy initializer would make
    // the server and client first paints disagree).
    const timer = setTimeout(() => {
      const prefs = loadPrefs();
      if (prefs.pxPerMs) setPxPerMsState(clampZoom(prefs.pxPerMs));
      if (prefs.snapEnabled !== undefined) setSnapEnabledState(prefs.snapEnabled);
      if (prefs.autoCrossfade !== undefined) setAutoCrossfadeState(prefs.autoCrossfade);
      if (isPreviewQuality(prefs.previewQuality)) setPreviewQualityState(prefs.previewQuality);
      if (prefs.theme === "light" || prefs.theme === "dark") setThemeState(prefs.theme);
    }, 0);
    return () => clearTimeout(timer);
  }, []);

  const persist = (patch: Record<string, unknown>) => {
    try {
      window.localStorage.setItem(PREFS_KEY, JSON.stringify({ ...loadPrefs(), ...patch }));
    } catch {
      // Private mode: prefs just don't persist.
    }
  };

  const setPxPerMs = useCallback((value: number) => {
    const clamped = clampZoom(value);
    setPxPerMsState(clamped);
    persist({ pxPerMs: clamped });
  }, []);

  const setTheme = useCallback((value: EditorTheme) => {
    setThemeState(value);
    persist({ theme: value });
  }, []);

  const setSnapEnabled = useCallback((value: boolean) => {
    setSnapEnabledState(value);
    persist({ snapEnabled: value });
  }, []);

  const setAutoCrossfade = useCallback((value: boolean) => {
    setAutoCrossfadeState(value);
    persist({ autoCrossfade: value });
  }, []);

  const setPreviewQuality = useCallback((value: PreviewQuality) => {
    setPreviewQualityState(value);
    persist({ previewQuality: value });
  }, []);

  const zoomBy = useCallback(
    (factor: number, anchorMs?: number) => {
      setPxPerMsState((previous) => {
        const next = clampZoom(previous * factor);
        const scroller = timelineScrollRef.current;
        if (scroller && anchorMs !== undefined) {
          // Keep anchorMs under the same screen x after the zoom.
          const anchorX = anchorMs * previous - scroller.scrollLeft;
          requestAnimationFrame(() => {
            scroller.scrollLeft = anchorMs * next - anchorX;
          });
        }
        persist({ pxPerMs: next });
        return next;
      });
    },
    [],
  );

  // Memoized so a provider re-render doesn't re-render every consumer; only
  // actual value changes do.
  const value = useMemo<EditorUIValue>(
    () => ({
      theme,
      setTheme,
      mode,
      setMode,
      editingLayoutId,
      setEditingLayoutId,
      editingSlotIndex,
      setEditingSlotIndex,
      editingTextId,
      setEditingTextId,
      pxPerMs,
      setPxPerMs,
      zoomBy,
      snapEnabled,
      setSnapEnabled,
      timelineTool,
      setTimelineTool,
      editMode,
      setEditMode,
      autoCrossfade,
      setAutoCrossfade,
      previewQuality,
      setPreviewQuality,
      setDropPreview,
      timelineScrollRef,
      setSnapGuideMs,
    }),
    [
      theme,
      setTheme,
      mode,
      setMode,
      editingLayoutId,
      setEditingLayoutId,
      editingSlotIndex,
      editingTextId,
      pxPerMs,
      setPxPerMs,
      zoomBy,
      snapEnabled,
      setSnapEnabled,
      timelineTool,
      editMode,
      autoCrossfade,
      setAutoCrossfade,
      previewQuality,
      setPreviewQuality,
      setDropPreview,
      setSnapGuideMs,
    ],
  );

  return (
    <EditorUIContext.Provider value={value}>
      <DragOverlayContext.Provider value={overlayStores}>
        {children}
      </DragOverlayContext.Provider>
    </EditorUIContext.Provider>
  );
}

function clampZoom(value: number): number {
  return clamp(value, MIN_PX_PER_MS, MAX_PX_PER_MS);
}

export function useEditorUI(): EditorUIValue {
  const context = useContext(EditorUIContext);
  if (!context) throw new Error("useEditorUI must be used inside <EditorUIProvider>");
  return context;
}

/**
 * Tiny parser for Google Fonts css2 responses: each `@font-face` block
 * becomes one face descriptor the export worker can register (workers can't
 * see `document.fonts`, so faces are re-created from their source URLs).
 */

export interface ParsedFontFace {
  /** font-weight descriptor: "400" or a variable range like "100 900". */
  weight?: string;
  /** font-style descriptor: "normal" | "italic" | oblique range. */
  style?: string;
  /** unicode-range descriptor (css2 ships one face per script subset). */
  unicodeRange?: string;
  url: string;
}

export function parseGoogleFontCss(css: string): ParsedFontFace[] {
  const faces: ParsedFontFace[] = [];
  for (const block of css.match(/@font-face\s*\{[^}]*\}/g) ?? []) {
    const url = /src:[^;}]*url\(([^)]+)\)/.exec(block)?.[1]?.replace(/^['"]|['"]$/g, "");
    if (!url) continue;
    const weight = /font-weight:\s*([^;}]+)/.exec(block)?.[1]?.trim();
    const style = /font-style:\s*([^;}]+)/.exec(block)?.[1]?.trim();
    const unicodeRange = /unicode-range:\s*([^;}]+)/.exec(block)?.[1]?.trim();
    faces.push({
      url,
      ...(weight ? { weight } : {}),
      ...(style ? { style } : {}),
      ...(unicodeRange ? { unicodeRange } : {}),
    });
  }
  return faces;
}

/** Does a font-weight descriptor ("400", "100 900") cover `wanted`? */
export function weightDescriptorMatches(descriptor: string | undefined, wanted: number): boolean {
  if (!descriptor) return true;
  const parts = descriptor.split(/\s+/).map(Number).filter(Number.isFinite);
  if (parts.length === 0) return true;
  const min = Math.min(...parts);
  const max = Math.max(...parts);
  return wanted >= min && wanted <= max;
}

"use client";

import { useEffect, useSyncExternalStore } from "react";
import type { ExportFontFaceInit } from "@mcut/media";
import { useEditor, useEditorState } from "@mcut/react";
import type { Project } from "@mcut/timeline";
import { parseGoogleFontCss, weightDescriptorMatches } from "./font-css";

/**
 * The editor's font system. Four tiers, mirroring what Figma/Canva/Photopea
 * converged on:
 *
 *  1. Generic CSS families — always available, zero loading.
 *  2. A curated Google Fonts catalog — loaded on demand via the css2 API +
 *     `document.fonts.load`, so the canvas never draws with a fallback face.
 *  3. System fonts via the Local Font Access API (`queryLocalFonts`,
 *     Chromium desktop only) — faces are registered into `document.fonts`
 *     from their binary blobs, which makes canvas rendering and PNG/video
 *     export deterministic instead of depending on OS name resolution.
 *  4. Uploaded font files (.ttf/.otf/.woff/.woff2) — the cross-browser
 *     fallback; persisted in IndexedDB and re-registered on boot.
 *
 * Everything funnels through {@link ensureFontLoaded}; export paths call
 * {@link ensureProjectFontsLoaded} before rendering (canvas `fillText` has
 * no reflow-on-load — drawing before the face is ready silently uses the
 * fallback font).
 */

export type FontSource = "generic" | "google" | "system" | "uploaded";
export type FontCategory = "sans-serif" | "serif" | "display" | "handwriting" | "monospace";

export interface FontOption {
  family: string;
  source: FontSource;
  category: FontCategory;
  /** Weights this family offers (system/uploaded: the discovered faces). */
  weights: number[];
  hasItalic: boolean;
  /** Continuous weight axis when the family is a variable font. */
  variableWeight?: { min: number; max: number };
}

export type SystemFontStatus = "unsupported" | "idle" | "loading" | "ready" | "denied";

export interface FontLibraryState {
  /** Generic + catalog + uploaded + system, in picker order. */
  options: FontOption[];
  systemStatus: SystemFontStatus;
  recents: string[];
}

// ---------------------------------------------------------------------------
// Curated Google Fonts catalog
// ---------------------------------------------------------------------------

interface GoogleFontEntry {
  family: string;
  category: FontCategory;
  weights: number[];
  italic?: boolean;
  /**
   * The family ships as a VARIABLE font on Google Fonts: css2 accepts a
   * `wght@min..max` range and any weight inside it renders a true
   * interpolated face (no synthetic bolding). `weights` then just lists the
   * named stops for the picker; min/max bound the axis.
   */
  variable?: boolean;
}

const W_FULL = [100, 200, 300, 400, 500, 600, 700, 800, 900];

