// ---------------------------------------------------------------------------
// Store (template-store pattern: module state + useSyncExternalStore)
// ---------------------------------------------------------------------------

const listeners = new Set<() => void>();
let snapshot: FontLibraryState | null = null;

function notify(): void {
  snapshot = null;
  for (const listener of listeners) listener();
}

interface SystemFace {
  postscriptName: string;
  style: string;
  weight: number;
  italic: boolean;
  data: LocalFontData;
}

interface UploadedRecord {
  id: string;
  family: string;
  weight: number;
  italic: boolean;
  data: ArrayBuffer;
}

let systemStatus: SystemFontStatus = "idle";
const systemFamilies = new Map<string, SystemFace[]>();
const uploadedRecords: UploadedRecord[] = [];

/** Local Font Access API (WICG, Chromium 103+ desktop). */
interface LocalFontData {
  postscriptName: string;
  fullName: string;
  family: string;
  style: string;
  blob(): Promise<Blob>;
}

declare global {
  interface Window {
    queryLocalFonts?: (options?: { postscriptNames?: string[] }) => Promise<LocalFontData[]>;
  }
}

export function isSystemFontAccessSupported(): boolean {
  return typeof window !== "undefined" && typeof window.queryLocalFonts === "function";
}

const RECENTS_KEY = "mcut:fonts:recents:v1";
const SYSTEM_ENABLED_KEY = "mcut:fonts:system-enabled:v1";
const MAX_RECENTS = 8;

function readRecents(): string[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = JSON.parse(window.localStorage.getItem(RECENTS_KEY) ?? "[]");
    return Array.isArray(raw) ? raw.filter((f): f is string => typeof f === "string") : [];
  } catch {
    return [];
  }
}

export function pushRecentFont(family: string): void {
  if (typeof window === "undefined") return;
  const next = [family, ...readRecents().filter((f) => f !== family)].slice(0, MAX_RECENTS);
  try {
    window.localStorage.setItem(RECENTS_KEY, JSON.stringify(next));
  } catch {
    // Private mode: recents just don't persist.
  }
  notify();
}

function buildSnapshot(): FontLibraryState {
  const uploaded = new Map<string, FontOption>();
  for (const record of uploadedRecords) {
    const existing = uploaded.get(record.family);
    if (existing) {
      if (!existing.weights.includes(record.weight)) {
        existing.weights = [...existing.weights, record.weight].sort((a, b) => a - b);
      }
      existing.hasItalic = existing.hasItalic || record.italic;
    } else {
      uploaded.set(record.family, {
        family: record.family,
        source: "uploaded",
        category: "sans-serif",
        weights: [record.weight],
        hasItalic: record.italic,
      });
    }
  }
  const system: FontOption[] = [...systemFamilies.entries()]
    .map(([family, faces]) => ({
      family,
      source: "system" as const,
      category: "sans-serif" as const,
      weights: [...new Set(faces.map((f) => f.weight))].sort((a, b) => a - b),
      hasItalic: faces.some((f) => f.italic),
    }))
    .sort((a, b) => a.family.localeCompare(b.family));
  const google: FontOption[] = GOOGLE_FONTS.map((entry) => ({
    family: entry.family,
    source: "google",
    category: entry.category,
    weights: entry.weights,
    hasItalic: entry.italic ?? false,
    ...(entry.variable && entry.weights.length > 1
      ? {
          variableWeight: {
            min: entry.weights[0]!,
            max: entry.weights[entry.weights.length - 1]!,
          },
        }
      : {}),
  }));
  return {
    options: [...uploaded.values(), ...system, ...google, ...GENERIC_FONTS],
    systemStatus: isSystemFontAccessSupported() ? systemStatus : "unsupported",
    recents: readRecents(),
  };
}

const SERVER_STATE: FontLibraryState = { options: [], systemStatus: "unsupported", recents: [] };

export function getFontLibraryState(): FontLibraryState {
  snapshot ??= buildSnapshot();
  return snapshot;
}

export function subscribeFontLibrary(onChange: () => void): () => void {
  listeners.add(onChange);
  return () => listeners.delete(onChange);
}

export function getFontLibraryServerState(): FontLibraryState {
  return SERVER_STATE;
}

export function findFontOption(family: string): FontOption | undefined {
  return getFontLibraryState().options.find((o) => o.family === family);
}

// ---------------------------------------------------------------------------
// Google Fonts loading (css2 stylesheet injection + document.fonts.load)
// ---------------------------------------------------------------------------

function googleCss2Url(entry: GoogleFontEntry, text?: string): string {
  const family = entry.family.replace(/ /g, "+");
  // Variable families load the whole wght axis once; static families list
  // their cuts. (A range request against a static family 400s, so the
  // `variable` flags must be accurate.)
  const min = entry.weights[0] ?? 400;
  const max = entry.weights[entry.weights.length - 1] ?? 400;
  const stops = entry.variable && max > min ? [`${min}..${max}`] : entry.weights;
  const axes = entry.italic
    ? `:ital,wght@${[
        ...stops.map((w) => `0,${w}`),
        ...stops.map((w) => `1,${w}`),
      ].join(";")}`
    : `:wght@${stops.join(";")}`;
  const subset = text ? `&text=${encodeURIComponent(text)}` : "";
  return `https://fonts.googleapis.com/css2?family=${family}${axes}${subset}&display=swap`;
}

const injectedStylesheets = new Map<string, Promise<void>>();

/** Resolves once the stylesheet is PARSED — only then does
 * `document.fonts.load` know the family and actually fetch the face. */
function injectStylesheet(url: string): Promise<void> {
  let pending = injectedStylesheets.get(url);
  if (!pending) {
    pending = new Promise<void>((resolve) => {
      const link = document.createElement("link");
      link.rel = "stylesheet";
      link.href = url;
      link.onload = () => resolve();
      link.onerror = () => resolve(); // offline: degrade to fallback face
      document.head.appendChild(link);
    });
    injectedStylesheets.set(url, pending);
  }
  return pending;
}

export function closestWeight(available: number[], wanted: number): number {
  return available.reduce(
    (best, w) => (Math.abs(w - wanted) < Math.abs(best - wanted) ? w : best),
    available[0] ?? 400,
  );
}

function fontLoadSpec(family: string, weight: number, italic: boolean): string {
  return `${italic ? "italic " : ""}${weight} 64px "${family}"`;
}

async function ensureGoogleFont(entry: GoogleFontEntry, weight: number, italic: boolean): Promise<void> {
  await injectStylesheet(googleCss2Url(entry));
  const min = entry.weights[0] ?? 400;
  const max = entry.weights[entry.weights.length - 1] ?? 400;
  const w = entry.variable
    ? Math.round(Math.min(max, Math.max(min, weight)))
    : closestWeight(entry.weights, weight);
  await document.fonts.load(fontLoadSpec(entry.family, w, italic && (entry.italic ?? false)));
}

/**
 * Cheap per-family preview for picker rows: a css2 request subset to just
 * the characters of the family name (~2–8 kB instead of the full face).
 */
export function ensureFontPreview(family: string): void {
  if (typeof document === "undefined") return;
  const entry = GOOGLE_FONTS.find((e) => e.family === family);
  if (!entry) return; // system/uploaded families resolve natively
  const preview: GoogleFontEntry = {
    ...entry,
    weights: [closestWeight(entry.weights, 400)],
    italic: false,
    variable: false,
  };
  void injectStylesheet(googleCss2Url(preview, family));
}

// ---------------------------------------------------------------------------
// System fonts (Local Font Access API)
// ---------------------------------------------------------------------------

function weightFromStyleName(style: string): number {
  const s = style.toLowerCase();
  if (/hairline|thin/.test(s)) return 100;
  if (/extra\s*-?light|ultra\s*-?light/.test(s)) return 200;
  if (/light/.test(s)) return 300;
  if (/medium/.test(s)) return 500;
  if (/semi\s*-?bold|demi/.test(s)) return 600;
  if (/extra\s*-?bold|ultra\s*-?bold/.test(s)) return 800;
  if (/black|heavy/.test(s)) return 900;
  if (/bold/.test(s)) return 700;
  return 400;
}

function isItalicStyleName(style: string): boolean {
  return /italic|oblique/i.test(style);
}

function indexSystemFonts(fonts: LocalFontData[]): void {
  systemFamilies.clear();
  for (const font of fonts) {
    const faces = systemFamilies.get(font.family) ?? [];
    faces.push({
      postscriptName: font.postscriptName,
      style: font.style,
      weight: weightFromStyleName(font.style),
      italic: isItalicStyleName(font.style),
      data: font,
    });
    systemFamilies.set(font.family, faces);
  }
}

/**
 * Enumerate system fonts. MUST be called from a user gesture the first time
 * (the browser shows a "local fonts" permission prompt); afterwards
 * {@link restoreSystemFonts} re-enumerates silently on boot.
 */
export async function loadSystemFonts(): Promise<boolean> {
  if (!isSystemFontAccessSupported()) return false;
  systemStatus = "loading";
  notify();
  try {
    const fonts = await window.queryLocalFonts!();
    indexSystemFonts(fonts);
    systemStatus = "ready";
    try {
      window.localStorage.setItem(SYSTEM_ENABLED_KEY, "1");
    } catch {
      // Private mode: re-enable manually next session.
    }
    notify();
    return true;
  } catch {
    systemStatus = "denied";
    notify();
    return false;
  }
}

/** Silent re-enumeration on boot when permission was already granted. */
async function restoreSystemFonts(): Promise<void> {
  if (!isSystemFontAccessSupported()) return;
  try {
    if (window.localStorage.getItem(SYSTEM_ENABLED_KEY) !== "1") return;
  } catch {
    return;
  }
  try {
    const status = await navigator.permissions.query({
      name: "local-fonts" as PermissionName,
    });
    if (status.state !== "granted") return;
  } catch {
    return; // permission name unknown: stay idle, the button still works
  }
  await loadSystemFonts();
}

const registeredSystemFamilies = new Set<string>();

/** Pick one face per (weight, italic) — fewest extra style tokens wins. */
function dedupeFaces(faces: SystemFace[]): SystemFace[] {
  const byKey = new Map<string, SystemFace>();
  for (const face of faces) {
    const key = `${face.weight}:${face.italic ? "i" : "n"}`;
    const existing = byKey.get(key);
    if (!existing || face.style.length < existing.style.length) byKey.set(key, face);
  }
  return [...byKey.values()];
}

/**
 * Register a system family's faces into `document.fonts` from their blobs.
 * After this, canvas drawing and `document.fonts.load` for the plain family
 * name are deterministic (no dependence on OS font name resolution).
 */
async function ensureSystemFamily(family: string): Promise<void> {
  if (registeredSystemFamilies.has(family)) return;
  const faces = systemFamilies.get(family);
  if (!faces || faces.length === 0) return;
  registeredSystemFamilies.add(family);
  const results = await Promise.allSettled(
    dedupeFaces(faces).map(async (face) => {
      const buffer = await (await face.data.blob()).arrayBuffer();
      const fontFace = new FontFace(family, buffer, {
        weight: String(face.weight),
        style: face.italic ? "italic" : "normal",
      });
      await fontFace.load();
      document.fonts.add(fontFace);
    }),
  );
  if (results.every((r) => r.status === "rejected")) {
    registeredSystemFamilies.delete(family); // retry next time
  }
}

// ---------------------------------------------------------------------------
// Uploaded fonts (IndexedDB persistence)
// ---------------------------------------------------------------------------

const DB_NAME = "mcut-fonts";
const DB_STORE = "uploaded";

function openFontDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => {
      if (!request.result.objectStoreNames.contains(DB_STORE)) {
        request.result.createObjectStore(DB_STORE, { keyPath: "id" });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error("IndexedDB unavailable"));
  });
}

async function dbPutFont(record: UploadedRecord): Promise<void> {
  const db = await openFontDb();
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(DB_STORE, "readwrite");
    tx.objectStore(DB_STORE).put(record);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error ?? new Error("font save failed"));
  });
  db.close();
}

async function dbListFonts(): Promise<UploadedRecord[]> {
  const db = await openFontDb();
  const records = await new Promise<UploadedRecord[]>((resolve, reject) => {
    const request = db.transaction(DB_STORE, "readonly").objectStore(DB_STORE).getAll();
    request.onsuccess = () => resolve(request.result as UploadedRecord[]);
    request.onerror = () => reject(request.error ?? new Error("font load failed"));
  });
  db.close();
  return records;
}

export async function removeUploadedFontFamily(family: string): Promise<void> {
  const removed = uploadedRecords.filter((r) => r.family === family);
  if (removed.length === 0) return;
  for (let i = uploadedRecords.length - 1; i >= 0; i--) {
    if (uploadedRecords[i]!.family === family) uploadedRecords.splice(i, 1);
  }
  notify();
  try {
    const db = await openFontDb();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(DB_STORE, "readwrite");
      for (const record of removed) tx.objectStore(DB_STORE).delete(record.id);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error ?? new Error("font delete failed"));
    });
    db.close();
  } catch {
    // Registered faces stay live this session; the DB row survives.
  }
}

/**
 * Minimal SFNT `name`-table reader: family (nameID 16, falling back to 1)
 * and subfamily (17 → 2) from TTF/OTF/TTC bytes. WOFF/WOFF2 tables are
 * compressed — callers fall back to the filename for those.
 */
function parseFontNames(buffer: ArrayBuffer): { family?: string; subfamily?: string } {
  try {
    const view = new DataView(buffer);
    let base = 0;
    if (view.getUint32(0) === 0x74746366 /* 'ttcf' */) base = view.getUint32(12);
    const tag = view.getUint32(base);
    if (tag !== 0x00010000 && tag !== 0x4f54544f /* 'OTTO' */ && tag !== 0x74727565 /* 'true' */) {
      return {};
    }
    const numTables = view.getUint16(base + 4);
    let nameTable = -1;
    for (let i = 0; i < numTables; i++) {
      const record = base + 12 + i * 16;
      if (view.getUint32(record) === 0x6e616d65 /* 'name' */) {
        nameTable = view.getUint32(record + 8);
        break;
      }
    }
    if (nameTable < 0) return {};
    const count = view.getUint16(nameTable + 2);
    const stringsStart = nameTable + view.getUint16(nameTable + 4);
    const names = new Map<number, string>();
    for (let i = 0; i < count; i++) {
      const record = nameTable + 6 + i * 12;
      const platformId = view.getUint16(record);
      const nameId = view.getUint16(record + 6);
      const length = view.getUint16(record + 8);
      const offset = stringsStart + view.getUint16(record + 10);
      if (nameId !== 1 && nameId !== 2 && nameId !== 16 && nameId !== 17) continue;
      let value = "";
      if (platformId === 3 || platformId === 0) {
        for (let j = 0; j + 1 < length; j += 2) value += String.fromCharCode(view.getUint16(offset + j));
      } else if (platformId === 1) {
        for (let j = 0; j < length; j++) value += String.fromCharCode(view.getUint8(offset + j));
      } else {
        continue;
      }
      // Windows (platform 3) entries win; others only fill gaps.
      if (value && (platformId === 3 || !names.has(nameId))) names.set(nameId, value);
    }
    return {
      family: names.get(16) ?? names.get(1),
      subfamily: names.get(17) ?? names.get(2),
    };
  } catch {
    return {};
  }
}

function familyFromFilename(filename: string): { family: string; subfamily: string } {
  const stem = filename.replace(/\.(ttf|otf|woff2?|ttc)$/i, "").replace(/[-_]+/g, " ");
  const styleWords =
    /\b(thin|extra ?light|ultra ?light|light|regular|normal|book|medium|semi ?bold|demi ?bold|bold|extra ?bold|ultra ?bold|black|heavy|italic|oblique)\b/gi;
  const styles = stem.match(styleWords) ?? [];
  const family = stem.replace(styleWords, "").replace(/\s+/g, " ").trim();
  return { family: family || stem.trim() || "Uploaded font", subfamily: styles.join(" ") || "Regular" };
}

async function registerUploadedRecord(record: UploadedRecord): Promise<void> {
  const fontFace = new FontFace(record.family, record.data, {
    weight: String(record.weight),
    style: record.italic ? "italic" : "normal",
  });
  await fontFace.load();
  document.fonts.add(fontFace);
}

/** Import font files: parse names, register faces, persist to IndexedDB. */
export async function uploadFontFiles(files: Iterable<File>): Promise<{ added: string[]; failed: string[] }> {
  const added: string[] = [];
  const failed: string[] = [];
  for (const file of files) {
    try {
      const data = await file.arrayBuffer();
      const parsed = parseFontNames(data);
      const fallback = familyFromFilename(file.name);
      const family = parsed.family ?? fallback.family;
      const subfamily = parsed.subfamily ?? fallback.subfamily;
      const record: UploadedRecord = {
        id: `font-${family}-${subfamily}`.toLowerCase().replace(/\s+/g, "-"),
        family,
        weight: weightFromStyleName(subfamily),
        italic: isItalicStyleName(subfamily),
        data,
      };
      await registerUploadedRecord(record);
      const existing = uploadedRecords.findIndex((r) => r.id === record.id);
      if (existing >= 0) uploadedRecords.splice(existing, 1);
      uploadedRecords.push(record);
      added.push(family);
      try {
        await dbPutFont(record);
      } catch {
        // Usable this session even if persistence fails.
      }
    } catch {
      failed.push(file.name);
    }
  }
  if (added.length > 0) notify();
  return { added, failed };
}

// ---------------------------------------------------------------------------
// Loading orchestration
// ---------------------------------------------------------------------------

const GENERIC_FAMILY_NAMES = new Set([
  ...GENERIC_FONTS.map((f) => f.family),
  "cursive",
  "fantasy",
  "system-ui",
  "ui-serif",
  "ui-sans-serif",
  "ui-monospace",
  "ui-rounded",
]);

/**
 * Make `family` at (`weight`, `italic`) drawable on a canvas. Resolves on a
 * best-effort basis — unknown families degrade to the fallback face rather
 * than rejecting.
 */
export async function ensureFontLoaded(family: string, weight = 400, italic = false): Promise<void> {
  if (typeof document === "undefined") return;
  const name = family.trim();
  // Stacks ("Arial, sans-serif") and generic keywords need no loading.
  if (GENERIC_FAMILY_NAMES.has(name) || name.includes(",")) return;
  try {
    const google = GOOGLE_FONTS.find((e) => e.family === name);
    if (google) {
      await ensureGoogleFont(google, weight, italic);
      return;
    }
    if (systemFamilies.has(name)) {
      await ensureSystemFamily(name);
    }
    // Uploaded faces register at init; system faces just registered; for
    // anything else this still resolves OS-installed names in Chromium.
    await document.fonts.load(fontLoadSpec(name, weight, italic));
  } catch {
    // Never block rendering on a font.
  }
}

interface FontSpec {
  family: string;
  weight: number;
  italic: boolean;
}

/** Unique font specs referenced by the project's text + caption elements. */
export function collectProjectFontSpecs(project: Project): FontSpec[] {
  const specs = new Map<string, FontSpec>();
  for (const track of project.tracks) {
    for (const element of track.elements) {
      if (element.type !== "text" && element.type !== "caption") continue;
      const style = element.style;
      const italic = "fontStyle" in style && style.fontStyle === "italic";
      const key = `${style.fontFamily}|${style.fontWeight}|${italic ? "i" : "n"}`;
      if (!specs.has(key)) {
        specs.set(key, { family: style.fontFamily, weight: style.fontWeight, italic });
      }
    }
  }
  return [...specs.values()];
}

/**
 * Load every font the project references — REQUIRED before any canvas
 * render that must be correct (PNG cover export, video export): canvas text
 * drawn before the face is ready silently uses the fallback font.
 */
export async function ensureProjectFontsLoaded(project: Project): Promise<void> {
  await Promise.allSettled(
    collectProjectFontSpecs(project).map((spec) => ensureFontLoaded(spec.family, spec.weight, spec.italic)),
  );
}

// ---------------------------------------------------------------------------
// Export worker fonts
// ---------------------------------------------------------------------------

/** Faces of a Google family the project actually uses (weights + styles). */
async function googleExportFaces(entry: GoogleFontEntry, specs: FontSpec[]): Promise<ExportFontFaceInit[]> {
  let css = "";
  try {
    const response = await fetch(googleCss2Url(entry));
    if (response.ok) css = await response.text();
  } catch {
    return []; // offline: the worker degrades to a fallback face, like the main thread
  }
  const min = entry.weights[0] ?? 400;
  const max = entry.weights[entry.weights.length - 1] ?? 400;
  const wantedWeights = new Set(
    specs.map((spec) =>
      entry.variable
        ? Math.round(Math.min(max, Math.max(min, spec.weight)))
        : closestWeight(entry.weights, spec.weight),
    ),
  );
  const wantItalic = new Set(specs.map((spec) => spec.italic && (entry.italic ?? false)));
  return parseGoogleFontCss(css)
    .filter((face) => {
      const italicFace = face.style?.includes("italic") ?? false;
      if (!wantItalic.has(italicFace)) return false;
      return [...wantedWeights].some((weight) => weightDescriptorMatches(face.weight, weight));
    })
    .map((face) => ({
      family: entry.family,
      ...(face.weight ? { weight: face.weight } : {}),
      ...(face.style ? { style: face.style } : {}),
      ...(face.unicodeRange ? { unicodeRange: face.unicodeRange } : {}),
      source: face.url,
    }));
}

/**
 * Resolve the project's font specs to faces the export worker can register
 * in its own `FontFaceSet` (workers can't see `document.fonts`): Google
 * faces as fetchable URLs (with unicode-range subsets), uploaded and system
 * faces as binary copies. Families neither in the catalog nor registered
 * from binaries resolve natively in the worker canvas, same as on main.
 */
export async function collectProjectFontExports(project: Project): Promise<ExportFontFaceInit[]> {
  const byFamily = new Map<string, FontSpec[]>();
  for (const spec of collectProjectFontSpecs(project)) {
    const name = spec.family.trim();
    if (GENERIC_FAMILY_NAMES.has(name) || name.includes(",")) continue;
    byFamily.set(name, [...(byFamily.get(name) ?? []), spec]);
  }

  const out: ExportFontFaceInit[] = [];
  for (const [family, specs] of byFamily) {
    const google = GOOGLE_FONTS.find((e) => e.family === family);
    if (google) {
      out.push(...(await googleExportFaces(google, specs)));
      continue;
    }
    const uploaded = uploadedRecords.filter((r) => r.family === family);
    if (uploaded.length > 0) {
      for (const record of uploaded) {
        out.push({
          family,
          weight: String(record.weight),
          style: record.italic ? "italic" : "normal",
          // Copy: the start message transfers (detaches) binary sources.
          source: record.data.slice(0),
        });
      }
      continue;
    }
    const faces = systemFamilies.get(family);
    if (!faces || faces.length === 0) continue;
    const chosen = new Map<string, SystemFace>();
    for (const spec of specs) {
      const styled = faces.filter((f) => f.italic === spec.italic);
      const pool = styled.length > 0 ? styled : faces;
      const weight = closestWeight([...new Set(pool.map((f) => f.weight))], spec.weight);
      const face = dedupeFaces(pool.filter((f) => f.weight === weight))[0];
      if (face) chosen.set(face.postscriptName, face);
    }
    for (const face of chosen.values()) {
      try {
        out.push({
          family,
          weight: String(face.weight),
          style: face.italic ? "italic" : "normal",
          source: await (await face.data.blob()).arrayBuffer(),
        });
      } catch {
        // Face unavailable: the worker falls back, same as a failed load here.
      }
    }
  }
  return out;
}

let initPromise: Promise<void> | null = null;

/** One-time boot: re-register uploaded fonts, silently restore system fonts. */
export function initFontLibrary(): Promise<void> {
  if (typeof window === "undefined") return Promise.resolve();
  initPromise ??= (async () => {
    try {
      const records = await dbListFonts();
      const results = await Promise.allSettled(records.map(registerUploadedRecord));
      uploadedRecords.push(...records.filter((_, i) => results[i]!.status === "fulfilled"));
      if (records.length > 0) notify();
    } catch {
      // No IndexedDB (private mode): uploads just don't persist.
    }
    await restoreSystemFonts();
  })();
  return initPromise;
}

/** Reactive view of the library (options, system status, recents). */
export function useFontLibrary(): FontLibraryState {
  return useSyncExternalStore(subscribeFontLibrary, getFontLibraryState, getFontLibraryServerState);
}

/**
 * Keep `document.fonts` in sync with the project: boots the library, then
 * loads any font a text/caption element references whenever the set changes.
 * The preview canvas redraws every frame, so faces pop in as they arrive.
 * Mount once inside the editor provider.
 */
export function useProjectFontLoader(): void {
  const engine = useEditor();
  const fontKey = useEditorState((s) =>
    collectProjectFontSpecs(s.project)
      .map((spec) => `${spec.family}|${spec.weight}|${spec.italic ? "i" : "n"}`)
      .sort()
      .join(","),
  );
  useEffect(() => {
    void initFontLibrary().then(() => ensureProjectFontsLoaded(engine.project));
  }, [fontKey, engine]);
}

"use client";

import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import {
  ensureFontLoaded,
  ensureFontPreview,
  isSystemFontAccessSupported,
  loadSystemFonts,
  pushRecentFont,
  uploadFontFiles,
  useFontLibrary,
  type FontCategory,
  type FontOption,
} from "./font-library";

/**
 * The font family picker (Figma/Canva-style): search, category filters,
 * recents on top, then uploaded → system → library groups — every row
 * rendered in its own typeface. System fonts arrive via the Local Font
 * Access API behind an explicit button (Chromium desktop); font-file upload
 * is the everywhere fallback.
 */

const CATEGORY_FILTERS: Array<{ key: FontCategory; label: string }> = [
  { key: "display", label: "Display" },
  { key: "sans-serif", label: "Sans" },
  { key: "serif", label: "Serif" },
  { key: "handwriting", label: "Script" },
  { key: "monospace", label: "Mono" },
];

const SOURCE_GROUPS: Array<{ source: FontOption["source"]; heading: string }> = [
  { source: "uploaded", heading: "Uploaded" },
  { source: "system", heading: "This computer" },
  { source: "google", heading: "Library" },
  { source: "generic", heading: "Defaults" },
];

function fontFamilyCss(family: string): string {
  return /[,"']/.test(family) ? family : `"${family}", sans-serif`;
}

function FontRow({
  option,
  selected,
  onPick,
}: {
  option: FontOption;
  selected: boolean;
  onPick: (family: string) => void;
}) {
  // Lazy per-family preview subset so the row shows its real face.
  useEffect(() => ensureFontPreview(option.family), [option.family]);
  return (
    <CommandItem
      value={option.family}
      keywords={[option.category]}
      className={cn("text-sm", selected && "bg-accent/60")}
      onSelect={() => onPick(option.family)}
    >
      <span className="truncate" style={{ fontFamily: fontFamilyCss(option.family) }}>
        {option.family}
      </span>
      {option.hasItalic && (
        <span className="ml-auto pl-2 text-2xs text-muted-foreground italic">i</span>
      )}
    </CommandItem>
  );
}

export function FontPicker({
  value,
  weight = 400,
  italic = false,
  onSelect,
  className,
}: {
  /** Current font family. */
  value: string;
  /** Current weight/style — preloaded for the picked family so the canvas updates without a fallback flash. */
  weight?: number;
  italic?: boolean;
  onSelect: (family: string) => void;
  className?: string;
}) {
  const [open, setOpen] = useState(false);
  const [category, setCategory] = useState<FontCategory | null>(null);
  const library = useFontLibrary();
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const pick = (family: string) => {
    setOpen(false);
    pushRecentFont(family);
    void ensureFontLoaded(family, weight, italic);
    onSelect(family);
  };

  const byFamily = new Map(library.options.map((o) => [o.family, o]));
  const recents = library.recents
    .map((family) => byFamily.get(family))
    .filter((o): o is FontOption => o !== undefined && (category === null || o.category === category));
  const groups = SOURCE_GROUPS.map(({ source, heading }) => ({
    heading,
    options: library.options.filter(
      (o) =>
        o.source === source &&
        // System families have no reliable category metadata; only the
        // library/default groups narrow under a category filter.
        (category === null || o.source === "system" || o.source === "uploaded" || o.category === category),
    ),
  })).filter((group) => group.options.length > 0);

  const onUpload = async (files: FileList | null) => {
    if (!files || files.length === 0) return;
    const { added, failed } = await uploadFontFiles(files);
    if (added.length > 0) toast.success(`Added ${[...new Set(added)].join(", ")}`);
    if (failed.length > 0) toast.error(`Could not read ${failed.join(", ")}`);
  };

  const onLoadSystemFonts = async () => {
    const ok = await loadSystemFonts();
    if (ok) toast.success("System fonts added to the picker");
    else toast.error("Font access was denied — check the site permission and try again");
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        render={
          <button
            type="button"
            className={cn(
              "flex h-7 w-full min-w-0 items-center rounded-md border border-input bg-transparent px-2 text-left text-xs hover:bg-accent/40",
              className,
            )}
            title="Change font"
          />
        }
      >
        <span className="truncate" style={{ fontFamily: fontFamilyCss(value) }}>
          {value}
        </span>
      </PopoverTrigger>
      <PopoverContent className="w-72 p-0" side="left" align="start">
        <Command>
          <CommandInput placeholder="Search fonts…" />
          <div className="flex gap-1 px-2 pt-1.5">
            {CATEGORY_FILTERS.map(({ key, label }) => (
              <Button
                key={key}
                size="xs"
                variant={category === key ? "secondary" : "ghost"}
                className="h-5 flex-1 px-1 text-2xs"
                onClick={() => setCategory(category === key ? null : key)}
              >
                {label}
              </Button>
            ))}
          </div>
          <CommandList className="max-h-72">
            <CommandEmpty>No fonts match.</CommandEmpty>
            {recents.length > 0 && (
              <CommandGroup heading="Recent">
                {recents.map((option) => (
                  <FontRow
                    key={`recent-${option.family}`}
                    option={option}
                    selected={option.family === value}
                    onPick={pick}
                  />
                ))}
              </CommandGroup>
            )}
            {groups.map((group) => (
              <CommandGroup key={group.heading} heading={group.heading}>
                {group.options.map((option) => (
                  <FontRow
                    key={option.family}
                    option={option}
                    selected={option.family === value}
                    onPick={pick}
                  />
                ))}
              </CommandGroup>
            ))}
          </CommandList>
          <div className="flex items-center gap-1.5 border-t border-border/60 p-1.5">
            {isSystemFontAccessSupported() && library.systemStatus !== "ready" && (
              <Button
                size="xs"
                variant="outline"
                className="flex-1"
                disabled={library.systemStatus === "loading"}
                onClick={() => void onLoadSystemFonts()}
              >
                {library.systemStatus === "loading" ? "Loading…" : "Use system fonts"}
              </Button>
            )}
            <Button
              size="xs"
              variant="outline"
              className="flex-1"
              onClick={() => fileInputRef.current?.click()}
            >
              Upload font…
            </Button>
            <input
              ref={fileInputRef}
              type="file"
              multiple
              accept=".ttf,.otf,.woff,.woff2,.ttc,font/*"
              className="hidden"
              onChange={(event) => {
                void onUpload(event.target.files);
                event.target.value = "";
              }}
            />
          </div>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { useEffect, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
import { useEditor, useEditorState } from "@mcut/react";
import type { EditorEngine, Layout, LayoutSlot } from "@mcut/timeline";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { useEditorUI } from "./editor-ui";
import { clamp, clamp01, roundTo } from "./math";
import { findTargetMulticam } from "./multicam-ui";

/**
 * On-canvas direct manipulation for a multicam layout, Figma-style: slots
 * are draggable boxes with eight resize handles (corners keep the aspect,
 * Shift frees it; edges stretch one axis), drags snap to the safe area /
 * canvas center / sibling slots with guide lines (⌘ disables), arrows nudge
 * by a pixel, and double-clicking a cover slot enters crop mode where
 * dragging pans the source inside the frame. Everything with a value — fit,
 * radius, shadow, aspect, exact position — lives in the inspector
 * (LayoutSlotInspector in properties-layout-slot.tsx), keyed off the shared
 * editingSlotIndex edit state. Every edit dispatches saveLayout, so the bank
 * tiles and program output restyle live.
 */

const MIN_SIZE = 0.05;
const CLICK_SLOP_PX = 4;
const SNAP_PX = 8;

/** Safe-area margin: 5% of the canvas short edge (uniform in pixels). */
export const SAFE_MARGIN = 0.05;

/** The safe-area rect in normalized canvas coordinates. */
export function safeAreaRect(width: number, height: number): LayoutSlot["rect"] {
  const margin = SAFE_MARGIN * Math.min(width, height);
  return {
    x: margin / width,
    y: margin / height,
    w: 1 - (2 * margin) / width,
    h: 1 - (2 * margin) / height,
  };
}

export function roundRect(rect: LayoutSlot["rect"]): LayoutSlot["rect"] {
  return {
    x: roundTo(rect.x, 3),
    y: roundTo(rect.y, 3),
    w: roundTo(rect.w, 3),
    h: roundTo(rect.h, 3),
  };
}

/** Patch one slot of a layout (shared with the inspector). */
export function saveLayoutSlot(
  engine: EditorEngine,
  layout: Layout,
  index: number,
  patch: Partial<LayoutSlot>,
  options?: { history?: boolean },
): void {
  try {
    engine.dispatch(
      {
        type: "saveLayout",
        layout: {
          ...layout,
          slots: layout.slots.map((s, i) => (i === index ? { ...s, ...patch } : s)),
        },
      },
      options,
    );
  } catch {
    // Layout vanished mid-edit.
  }
}

/** Closest snap candidate to any of `positions` within `threshold`. */
function snapAxis(
  positions: number[],
  candidates: number[],
  threshold: number,
): { delta: number; guide: number | null } {
  let best: { delta: number; guide: number } | null = null;
  for (const position of positions) {
    for (const candidate of candidates) {
      const delta = candidate - position;
      if (Math.abs(delta) <= threshold && (!best || Math.abs(delta) < Math.abs(best.delta))) {
        best = { delta, guide: candidate };
      }
    }
  }
  return best ?? { delta: 0, guide: null };
}

/** Snap targets on one axis: canvas edges/center, safe area, sibling slots. */
function axisCandidates(
  layout: Layout,
  skipIndex: number,
  safe: LayoutSlot["rect"],
  axis: "x" | "y",
): number[] {
  const candidates =
    axis === "x" ? [0, safe.x, 0.5, safe.x + safe.w, 1] : [0, safe.y, 0.5, safe.y + safe.h, 1];
  layout.slots.forEach((slot, i) => {
    if (i === skipIndex) return;
    const start = axis === "x" ? slot.rect.x : slot.rect.y;
    const length = axis === "x" ? slot.rect.w : slot.rect.h;
    candidates.push(start, start + length / 2, start + length);
  });
  return candidates;
}

type HandleId = "nw" | "n" | "ne" | "e" | "se" | "s" | "sw" | "w";

const HANDLES: ReadonlyArray<{ id: HandleId; x: number; y: number; cursor: string }> = [
  { id: "nw", x: 0, y: 0, cursor: "nwse-resize" },
  { id: "n", x: 0.5, y: 0, cursor: "ns-resize" },
  { id: "ne", x: 1, y: 0, cursor: "nesw-resize" },
  { id: "e", x: 1, y: 0.5, cursor: "ew-resize" },
  { id: "se", x: 1, y: 1, cursor: "nwse-resize" },
  { id: "s", x: 0.5, y: 1, cursor: "ns-resize" },
  { id: "sw", x: 0, y: 1, cursor: "nesw-resize" },
  { id: "w", x: 0, y: 0.5, cursor: "ew-resize" },
];

interface Guides {
  x: number | null;
  y: number | null;
  /** True while a drag is live (shows the safe-area outline). */
  active: boolean;
}

const NO_GUIDES: Guides = { x: null, y: null, active: false };

function SlotBox({
  layout,
  slot,
  index,
  selected,
  cropping,
  sourceSize,
  onSelect,
  onToggleCrop,
  setGuides,
}: {
  layout: Layout;
  slot: LayoutSlot;
  index: number;
  selected: boolean;
  cropping: boolean;
  /** Natural pixel size of the source filling this slot (for crop panning). */
  sourceSize: { width: number; height: number } | null;
  onSelect: (index: number) => void;
  onToggleCrop: (index: number) => void;
  setGuides: (guides: Guides) => void;
}) {
  const engine = useEditor();
  const dragRef = useRef<{
    mode: "move" | "resize" | "crop";
    handle: HandleId | null;
    startX: number;
    startY: number;
    rect: LayoutSlot["rect"];
    focus: { x: number; y: number };
    /** How many container px of the source overflow the slot per axis (crop). */
    overflow: { x: number; y: number };
    container: DOMRect;
    moved: boolean;
  } | null>(null);

  const save = (patch: Partial<LayoutSlot>) => saveLayoutSlot(engine, layout, index, patch);

  const begin = (
    mode: "move" | "resize" | "crop",
    event: ReactPointerEvent<HTMLElement>,
    handle: HandleId | null = null,
  ) => {
    event.stopPropagation();
    const container = (
      event.currentTarget.closest("[data-mcut-slot-editor]") as HTMLElement
    ).getBoundingClientRect();
    const overflow = { x: 0, y: 0 };
    if (mode === "crop" && sourceSize) {
      const slotW = slot.rect.w * container.width;
      const slotH = slot.rect.h * container.height;
      const scale = Math.max(slotW / sourceSize.width, slotH / sourceSize.height);
      overflow.x = sourceSize.width * scale - slotW;
      overflow.y = sourceSize.height * scale - slotH;
    }
    dragRef.current = {
      mode,
      handle,
      startX: event.clientX,
      startY: event.clientY,
      rect: slot.rect,
      focus: slot.focus ?? { x: 0.5, y: 0.5 },
      overflow,
      container,
      moved: false,
    };
    engine.beginTransaction();
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const onPointerMove = (event: ReactPointerEvent<HTMLElement>) => {
    const drag = dragRef.current;
    if (!drag) return;
    const dxPx = event.clientX - drag.startX;
    const dyPx = event.clientY - drag.startY;
    if (Math.hypot(dxPx, dyPx) > CLICK_SLOP_PX) drag.moved = true;
    if (!drag.moved) return;

    if (drag.mode === "crop") {
      // Dragging the content right reveals more of the source's left side,
      // so the focus moves opposite the pointer — and only where the cover
      // crop actually overflows the slot.
      const fx = drag.overflow.x > 1 ? clamp01(drag.focus.x - dxPx / drag.overflow.x) : drag.focus.x;
      const fy = drag.overflow.y > 1 ? clamp01(drag.focus.y - dyPx / drag.overflow.y) : drag.focus.y;
      save({ focus: { x: roundTo(fx, 3), y: roundTo(fy, 3) } });
      return;
    }

    const dx = dxPx / drag.container.width;
    const dy = dyPx / drag.container.height;
    const snapOff = event.metaKey || event.ctrlKey;
    const safe = safeAreaRect(engine.project.width, engine.project.height);
    const candidatesX = axisCandidates(layout, index, safe, "x");
    const candidatesY = axisCandidates(layout, index, safe, "y");
    const thresholdX = SNAP_PX / drag.container.width;
    const thresholdY = SNAP_PX / drag.container.height;
    const r = drag.rect;

    if (drag.mode === "move") {
      let x = clamp(r.x + dx, -0.45, 1.45 - r.w);
      let y = clamp(r.y + dy, -0.45, 1.45 - r.h);
      let guideX: number | null = null;
      let guideY: number | null = null;
      if (!snapOff) {
        const snapX = snapAxis([x, x + r.w / 2, x + r.w], candidatesX, thresholdX);
        x += snapX.delta;
        guideX = snapX.guide;
        const snapY = snapAxis([y, y + r.h / 2, y + r.h], candidatesY, thresholdY);
        y += snapY.delta;
        guideY = snapY.guide;
      }
      setGuides({ x: guideX, y: guideY, active: true });
      save({ rect: roundRect({ ...r, x, y }) });
      return;
    }

    const handle = drag.handle!;
    const corner = handle.length === 2;
    const locked = corner && !event.shiftKey;
    const dominantX = Math.abs(dxPx) >= Math.abs(dyPx);
    const right = r.x + r.w;
    const bottom = r.y + r.h;
    let w = handle.includes("e") ? r.w + dx : handle.includes("w") ? r.w - dx : r.w;
    let h = handle.includes("s") ? r.h + dy : handle.includes("n") ? r.h - dy : r.h;
    const ratio = r.w / r.h;
    if (locked) {
      if (dominantX) h = w / ratio;
      else w = h * ratio;
    }
    let guideX: number | null = null;
    let guideY: number | null = null;
    if (!snapOff) {
      // Snap the moving edges; with the aspect locked only the dominant axis
      // snaps, then the other re-derives so the ratio survives.
      if ((!locked || dominantX) && handle.includes("e")) {
        const snap = snapAxis([r.x + w], candidatesX, thresholdX);
        w += snap.delta;
        guideX = snap.guide;
      }
      if ((!locked || dominantX) && handle.includes("w")) {
        const snap = snapAxis([right - w], candidatesX, thresholdX);
        w -= snap.delta;
        guideX = snap.guide;
      }
      if ((!locked || !dominantX) && handle.includes("s")) {
        const snap = snapAxis([r.y + h], candidatesY, thresholdY);
        h += snap.delta;
        guideY = snap.guide;
      }
      if ((!locked || !dominantX) && handle.includes("n")) {
        const snap = snapAxis([bottom - h], candidatesY, thresholdY);
        h -= snap.delta;
        guideY = snap.guide;
      }
      if (locked) {
        if (dominantX) h = w / ratio;
        else w = h * ratio;
      }
    }
    w = clamp(w, MIN_SIZE, 3);
    h = clamp(h, MIN_SIZE, 3);
    const x = handle.includes("w") ? right - w : r.x;
    const y = handle.includes("n") ? bottom - h : r.y;
    setGuides({ x: guideX, y: guideY, active: true });
    save({ rect: roundRect({ x, y, w, h }) });
  };

  const end = (event: ReactPointerEvent<HTMLElement>) => {
    const drag = dragRef.current;
    if (!drag) return;
    dragRef.current = null;
    engine.endTransaction();
    setGuides(NO_GUIDES);
    event.currentTarget.releasePointerCapture(event.pointerId);
    // A press that never moved is a click: select the slot for the inspector.
    if (!drag.moved && drag.mode !== "resize") onSelect(index);
  };

  return (
    <div
      className={cn(
        "absolute border-2 bg-primary/10 hover:bg-primary/15",
        cropping
          ? "cursor-grab border-dashed border-primary active:cursor-grabbing"
          : selected
            ? "cursor-move border-primary"
            : "cursor-move border-primary/50",
      )}
      style={{
        left: `${slot.rect.x * 100}%`,
        top: `${slot.rect.y * 100}%`,
        width: `${slot.rect.w * 100}%`,
        height: `${slot.rect.h * 100}%`,
        // Mirror the render's rounding so radius edits read on the overlay too.
        borderRadius: `${slot.cornerRadius * 100}%`,
      }}
      onPointerDown={(event) => begin(cropping ? "crop" : "move", event)}
      onPointerMove={onPointerMove}
      onPointerUp={end}
      onPointerCancel={end}
      onDoubleClick={() => slot.fit === "cover" && onToggleCrop(index)}
    >
      <span className="absolute top-0.5 left-1.5 rounded-sm bg-overlay/60 px-1 text-2xs text-overlay-foreground/90 capitalize">
        {slot.source}
      </span>
      {selected &&
        !cropping &&
        HANDLES.map((handle) => (
          <span
            key={handle.id}
            data-handle={handle.id}
            className="absolute size-2.5 rounded-[2px] border border-overlay/40 bg-primary"
            style={{
              left: `${handle.x * 100}%`,
              top: `${handle.y * 100}%`,
              transform: "translate(-50%, -50%)",
              cursor: handle.cursor,
            }}
            onPointerDown={(event) => begin("resize", event, handle.id)}
            onPointerMove={onPointerMove}
            onPointerUp={end}
            onPointerCancel={end}
          />
        ))}
    </div>
  );
}

/** Mounted over the preview while a layout is being edited (multicam mode). */
export function LayoutSlotEditor() {
  const engine = useEditor();
  const { editingLayoutId, setEditingLayoutId, editingSlotIndex, setEditingSlotIndex } =
    useEditorUI();
  const [cropIndex, setCropIndex] = useState<number | null>(null);
  const [guides, setGuides] = useState<Guides>(NO_GUIDES);
  const layout = useEditorState((s) =>
    editingLayoutId ? s.project.layouts.find((l) => l.id === editingLayoutId) : undefined,
  );
  const selectedIds = useEditorState((s) => s.selection.elementIds);
  const lastLayoutRef = useRef<string | null>(null);

  // Entering a layout opens its topmost slot (usually the PiP) in the
  // inspector, so the panel is immediately useful.
  useEffect(() => {
    if (editingLayoutId === lastLayoutRef.current) return;
    lastLayoutRef.current = editingLayoutId;
    setCropIndex(null);
    if (editingLayoutId && layout) setEditingSlotIndex(layout.slots.length - 1);
  }, [editingLayoutId, layout, setEditingSlotIndex]);

  // Esc walks out one level (crop → slot selection → editor); arrows nudge
  // the selected slot by a pixel (Shift = 10). Capture phase so the global
  // playhead/selection hotkeys don't also fire.
  useEffect(() => {
    if (!layout) return;
    const onKeyDown = (event: KeyboardEvent) => {
      const target = event.target;
      if (
        target instanceof HTMLInputElement ||
        target instanceof HTMLTextAreaElement ||
        (target instanceof HTMLElement && target.isContentEditable)
      ) {
        return;
      }
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        if (cropIndex !== null) setCropIndex(null);
        else if (editingSlotIndex !== null) setEditingSlotIndex(null);
        else setEditingLayoutId(null);
        return;
      }
      if (!event.key.startsWith("Arrow") || editingSlotIndex === null) return;
      const slot = layout.slots[editingSlotIndex];
      if (!slot) return;
      event.preventDefault();
      event.stopPropagation();
      const px = event.shiftKey ? 10 : 1;
      const dx = event.key === "ArrowLeft" ? -px : event.key === "ArrowRight" ? px : 0;
      const dy = event.key === "ArrowUp" ? -px : event.key === "ArrowDown" ? px : 0;
      saveLayoutSlot(engine, layout, editingSlotIndex, {
        rect: roundRect({
          ...slot.rect,
          x: clamp(slot.rect.x + dx / engine.project.width, -0.45, 1.45 - slot.rect.w),
          y: clamp(slot.rect.y + dy / engine.project.height, -0.45, 1.45 - slot.rect.h),
        }),
      });
    };
    window.addEventListener("keydown", onKeyDown, true);
    return () => window.removeEventListener("keydown", onKeyDown, true);
  }, [engine, layout, cropIndex, editingSlotIndex, setEditingLayoutId, setEditingSlotIndex]);

  if (!layout) return null;

  // Crop panning needs the source's natural size; resolve it through the
  // multicam the bank targets (selected, else under playhead, else first).
  const target = findTargetMulticam(
    engine.project,
    selectedIds,
    engine.playback.state.currentTimeMs,
  );
  const sourceSize = (key: string) => {
    const source = target?.element.sources.find((s) => s.key === key);
    const asset = source ? engine.project.assets[source.assetId] : undefined;
    return asset?.width && asset?.height ? { width: asset.width, height: asset.height } : null;
  };

  const safe = safeAreaRect(engine.project.width, engine.project.height);

  return (
    <div
      data-mcut-slot-editor=""
      className="absolute inset-0 z-10"
      onPointerDown={(event) => {
        // Clicking empty canvas steps out of crop mode / slot selection.
        if (event.target !== event.currentTarget) return;
        setCropIndex(null);
        setEditingSlotIndex(null);
      }}
    >
      {guides.active && (
        <div
          className="pointer-events-none absolute border border-dashed border-(--snap-guide)/50"
          style={{
            left: `${safe.x * 100}%`,
            top: `${safe.y * 100}%`,
            width: `${safe.w * 100}%`,
            height: `${safe.h * 100}%`,
          }}
        />
      )}
      {guides.x !== null && (
        <div
          className="pointer-events-none absolute inset-y-0 w-px bg-(--snap-guide)"
          style={{ left: `${guides.x * 100}%` }}
        />
      )}
      {guides.y !== null && (
        <div
          className="pointer-events-none absolute inset-x-0 h-px bg-(--snap-guide)"
          style={{ top: `${guides.y * 100}%` }}
        />
      )}
      {layout.slots.map((slot, index) => (
        <SlotBox
          key={`${slot.source}-${index}`}
          layout={layout}
          slot={slot}
          index={index}
          selected={editingSlotIndex === index}
          cropping={cropIndex === index}
          sourceSize={sourceSize(slot.source)}
          onSelect={(i) => {
            setEditingSlotIndex(i);
            if (cropIndex !== null && cropIndex !== i) setCropIndex(null);
          }}
          onToggleCrop={(i) => {
            setEditingSlotIndex(i);
            setCropIndex((current) => (current === i ? null : i));
          }}
          setGuides={setGuides}
        />
      ))}
      <div className="absolute top-2 left-1/2 flex -translate-x-1/2 items-center gap-2 rounded-lg bg-overlay/65 px-2 py-1">
        <span className="text-2xs text-overlay-foreground/90">
          {cropIndex !== null
            ? "Drag inside the slot to pan its crop — Esc or double-click to finish"
            : `Editing “${layout.name}” — style it in the inspector`}
        </span>
        <Button
          size="xs"
          variant="secondary"
          onClick={() => {
            setCropIndex(null);
            setEditingSlotIndex(null);
            setEditingLayoutId(null);
          }}
        >
          Done
        </Button>
      </div>
    </div>
  );
}

import {
  getActiveAngleIndex,
  type EditorEngine,
  type MulticamElement,
  type Project,
} from "@mcut/timeline";

/**
 * Multicam UI helpers: which multicam the mode operates on, and the
 * playing-vs-paused switch semantics (Premiere parity — see the plan doc).
 */

export interface LocatedMulticam {
  element: MulticamElement;
  trackId: Project["tracks"][number]["id"];
}

/** The multicam the bank/hotkeys target: selected first, else under playhead, else first. */
export function findTargetMulticam(
  project: Project,
  selectedIds: readonly string[],
  playheadMs: number,
): LocatedMulticam | null {
  let underPlayhead: LocatedMulticam | null = null;
  let first: LocatedMulticam | null = null;
  for (const track of project.tracks) {
    for (const element of track.elements) {
      if (element.type !== "multicam") continue;
      const located = { element, trackId: track.id };
      if (selectedIds.includes(element.id)) return located;
      if (
        !underPlayhead &&
        playheadMs >= element.startMs &&
        playheadMs < element.startMs + element.durationMs
      ) {
        underPlayhead = located;
      }
      if (!first) first = located;
    }
  }
  return underPlayhead ?? first;
}

/**
 * The multicam switch gesture: while PLAYING a press cuts at the playhead
 * (you're performing the edit live); while PAUSED it corrects the layout of
 * the span under the playhead. This split is what makes multicam editing
 * fast — copy Premiere exactly.
 */
export function switchToLayout(
  engine: EditorEngine,
  element: MulticamElement,
  layoutId: string,
): void {
  const playheadMs = engine.playback.state.currentTimeMs;
  const localMs = Math.round(playheadMs - element.startMs);
  if (localMs < 0 || localMs >= element.durationMs) return;
  try {
    if (engine.playback.state.isPlaying && localMs > 0) {
      engine.dispatch({ type: "addAngleCut", elementId: element.id, atMs: localMs, layoutId });
    } else {
      const span = element.angles[getActiveAngleIndex(element.angles, localMs)];
      if (!span) return;
      engine.dispatch({
        type: "setAngleLayout",
        elementId: element.id,
        atMs: span.atMs,
        layoutId,
      });
    }
  } catch {
    // Cut collided with an existing one at the same ms: ignore.
  }
}
